public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = in.nextInt();
        }

        int eng = a[0];
        int orin = 1;
        for (int i = 1; i < n; i++) {
            if (a[i] > eng) {
                eng = a[i];
            }
        }

        System.out.println(eng + " " + orin);
    }
}

